SELECT (edc_codigo IS NOT DISTINCT FROM (SELECT edc_codigo FROM especie_documento WHERE UPPER(TRIM(edc_descricao)) = 'BOLETO PAGAR' ORDER BY (UPPER(TRIM(edc_sigla)) = 'BP') DESC, (UPPER(TRIM(edc_genero)) = 'P') DESC, edc_codigo LIMIT 1)) AS especie_ok, ctp_id AS ja_existe FROM conta_a_pagar WHERE ctp_id = (SELECT codigo_vf FROM migracao_multiloja.vinculo WHERE loj_codigo = {{loja_destino}} AND tipo = 'conta_pagar' AND codigo_origem = %(ctp_id)s::text)
